/* ── Date helpers (UTC-anchored so the server timezone can never shift a day) ─ */
const pad2 = (n) => String(n).padStart(2, '0');
const ymd = (y, m, d) => `${y}-${pad2(m)}-${pad2(d)}`;

function daysInMonth(y, monthIdx0) { return new Date(Date.UTC(y, monthIdx0 + 1, 0)).getUTCDate(); }

/** 'YYYY-MM-DD' of the nth (1-based) weekday (0=Sun) in a month. */
function nthWeekday(y, monthIdx0, weekday, n) {
  const first = new Date(Date.UTC(y, monthIdx0, 1)).getUTCDay();
  let day = 1 + ((weekday - first + 7) % 7) + (n - 1) * 7;
  while (day > daysInMonth(y, monthIdx0)) day -= 7;
  return ymd(y, monthIdx0 + 1, day);
}

/** Anonymous Gregorian computus → 'YYYY-MM-DD'. */
function easterSunday(y) {
  const a = y % 19;
  const b = Math.floor(y / 100);
  const c = y % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31);
  const day = ((h + l - 7 * m + 114) % 31) + 1;
  return ymd(y, month, day);
}

const shiftYmd = (s, days) => {
  const t = new Date(`${s}T00:00:00Z`).getTime() + days * 86400000;
  return new Date(t).toISOString().slice(0, 10);
};

/* ── Weekday-rule observances (computed, therefore always correct) ─────────── */
// resolve(year) → 'YYYY-MM-DD'. Built on the Date object so there is no
// hand-written date arithmetic to get wrong.
const WEEKDAY_RULES = [
  { name: "Mother's Day",       scope: W, kind: 'observance', themes: ['women-children', 'social-inclusion', 'health'],
    resolve: (y) => nthWeekday(y, 4, 0, 2) },   // 2nd Sunday of May
  { name: 'World Kindness Day', scope: W, kind: 'observance', themes: ['community', 'education', 'rights'],
    resolve: (y) => nthWeekday(y, 10, 2, 2) },  // 2nd Tuesday of November
  { name: 'Good Friday',        scope: W, kind: 'religious', themes: ['community'],
    resolve: (y) => shiftYmd(easterSunday(y), -2) },
];

/* ── Public API ───────────────────────────────────────────────────────────── */

export const SUPPORTED_LUNAR_YEARS = Object.keys(BY_YEAR).map(Number).sort();

/** Years that have curated data (fixed rules work for every year). */
export const availableYears = () => {
  const now = new Date().getUTCFullYear();
  const years = new Set([...SUPPORTED_LUNAR_YEARS]);
  for (let y = now - 3; y <= now + 3; y++) years.add(y);
  return [...years].sort((a, b) => a - b);
};

const norm = (row) => {
  // `m`/`d` are authoring scaffolding for the fixed rules — never ship them.
  const { m, d, ...rest } = row;
  return {
    scope: 'worldwide',
    kind: 'observance',
    themes: [],
    precision: 'fixed',
    source: 'curated',
    note: null,
    ...rest,
    themes: Array.isArray(rest.themes) ? rest.themes : [],
  };
};

/**
 * Every curated observance/festival whose date falls inside [startYmd, endYmd).
 * Purely deterministic — the input range is the only thing that varies.
 *
 * @param {string} startYmd  inclusive, 'YYYY-MM-DD'
 * @param {string} endYmd    exclusive, 'YYYY-MM-DD'
 * @param {object} opts      { scope: 'all' | 'worldwide' | 'india' }
 */
export function getObservancesInRange(startYmd, endYmd, opts = {}) {
  const scope = ['all', 'worldwide', 'india'].includes(opts.scope) ? opts.scope : 'all';
  const inScope = (s) => scope === 'all' || s === scope;
  const out = [];

  const startDate = new Date(`${startYmd}T00:00:00Z`);
  const endDate = new Date(`${endYmd}T00:00:00Z`);
  if (Number.isNaN(startDate.getTime()) || Number.isNaN(endDate.getTime()) || endDate <= startDate) return out;

  const startYear = startDate.getUTCFullYear();
  const endYear = endDate.getUTCFullYear();

  for (let y = startYear; y <= endYear; y++) {
    // 1. Fixed month/day rules.
    for (const row of FIXED) {
      if (!inScope(row.scope)) continue;
      const d = ymd(y, row.m, row.d);
      if (d >= startYmd && d < endYmd) out.push(norm({ ...row, date: d }));
    }
    // 2. Per-year festival rows (omitted entirely when the year has no data).
    for (const row of BY_YEAR[y] || []) {
      if (!inScope(row.scope)) continue;
      if (row.date >= startYmd && row.date < endYmd) out.push(norm({ ...row }));
    }
    // 3. Computed weekday rules.
    for (const rule of WEEKDAY_RULES) {
      if (!inScope(rule.scope)) continue;
      const s = rule.resolve(y);
      if (s >= startYmd && s < endYmd) out.push(norm({ ...rule, date: s }));
    }
  }

  out.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.name.localeCompare(b.name)));
  return out;
}

/** The observances on one specific calendar day (used by the suggestion flow). */
export function getObservancesOnDate(dateYmd) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(dateYmd || ''))) return [];
  const d = new Date(`${dateYmd}T00:00:00Z`);
  const next = new Date(d.getTime() + 86400000);
  return getObservancesInRange(dateYmd, next.toISOString().slice(0, 10), { scope: 'all' });
}

/** Union of every theme slug used by the dataset — handy for prompt grounding. */
export function allThemes() {
  const s = new Set();
  for (const r of FIXED) for (const t of r.themes || []) s.add(t);
  for (const rows of Object.values(BY_YEAR)) for (const r of rows) for (const t of r.themes || []) s.add(t);
  for (const r of WEEKDAY_RULES) for (const t of r.themes || []) s.add(t);
  return [...s].sort();
}

/**
 * Merge operator-managed `holidays` rows over the curated list. A DB row with the
 * same date + name replaces the curated entry (so corrections win) and anything
 * else is appended as an extra entry. Never throws — a DB failure degrades to
 * the curated list only.
 */
export function mergeCustomObservances(list, holidayRows) {
  const out = list.map((o) => ({ ...o }));
  const key = (o) => `${o.date}::${String(o.name).trim().toLowerCase()}`;
  const seen = new Set(out.map(key));
  for (const h of holidayRows || []) {
    const date = String(h.date || '').slice(0, 10);
    const name = String(h.name || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !name) continue;
    const k = `${date}::${name.toLowerCase()}`;
    // A curated row with the same name on the same day IS the same occasion. An
    // operator correcting or re-scoping it in the holidays table must win, so
    // replace the curated copy instead of dropping the new row on the floor.
    const at = out.findIndex((o) => key(o) === k);
    if (at !== -1) {
      out[at] = {
        ...out[at],
        date,
        name,
        scope: h.ngo_id ? 'india' : 'worldwide',
        kind: out[at].kind,
        themes: out[at].themes,
        precision: out[at].precision,
        note: h.description || h.note || out[at].note,
        source: 'db',
      };
      continue;
    }
    if (seen.has(k)) continue;
    seen.add(k);
    out.push({
      date,
      name,
      scope: h.ngo_id ? 'india' : 'worldwide',
      kind: 'observance',
      themes: [],
      precision: 'fixed',
      source: 'db',
      note: h.description || h.note || null,
    });
  }
  out.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.name.localeCompare(b.name)));
  return out;
}
